// A simple Matrix type alias to match the signature expectation.
type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(shape.len() == 2, "shape must have length 2");
    assert!(!a.is_empty(), "input array must have positive length");

    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "R and C must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must match either R or C"
    );

    let mut ret: Matrix<i8> = Vec::with_capacity(r);

    if n == r {
        // Treat as column vector: value depends on row index i.
        for i in 0..r {
            let v = a[i];
            let mut row = Vec::with_capacity(c);
            row.resize(c, v);
            ret.push(row);
        }
    } else {
        // Treat as row vector: value depends on column index j.
        for _i in 0..r {
            // Duplicate the whole array as the row.
            // Safe because n == c in this branch.
            ret.push(a.clone());
        }
    }

    ret
}